SELECT u.component, dn.blood_group, count(u.unit_id)::int AS at_risk_count, min(u.expires_on) AS nearest_expiry FROM blood_unit u JOIN donation d ON d.donation_id = u.donation_id JOIN donor dn ON dn.donor_id = d.donor_id WHERE u.status = 'AVAILABLE' AND u.expires_on BETWEEN CURRENT_DATE AND (CURRENT_DATE + 7) GROUP BY u.component, dn.blood_group HAVING count(u.unit_id) > 0 ORDER BY nearest_expiry ASC;
